fn resize_busy(_: &Workspace) -> bool { false }
#[test]
#[ignore = "手动 UI 分片重排/真实 PTY 响应；CONGMINAL_UI_ROUNDS 控制轮数"]
fn bench_ui_resize() {
    let rounds: usize = std::env::var("CONGMINAL_UI_ROUNDS").ok().and_then(|v| v.parse().ok()).unwrap_or(8);
    assert!((1..=1000).contains(&rounds));
    let mut app = workspace(); app.width = 1200; app.height = 700;
    app.add(Some(Axis::Across)); app.add(Some(Axis::Down)); app.select(1); app.add(Some(Axis::Down));
    wait(&mut app, |a| !resize_busy(a));
    for i in 0..app.panes.len() {
        app.load(i); app.driver.session.term.set_scrollback_limit(1_000_000);
        let width = app.driver.session.term.cols();
        let content = if i.is_multiple_of(2) { "x".repeat(1_500_000) }
            else { format!("{}\r\n", "x".repeat(width - 1)).repeat(20000) };
        vt::Parser::new().advance(&mut app.driver.session.term, content.as_bytes());
    }
    app.restore();
    let mut tick_hist = [0u32; 2001]; let mut tick_max = 0;
    let mut key_hist = [0u32; 2001]; let mut key_max = 0;
    let mut paint_max = 0; let mut pending_turns = 0; let mut tick_count = 0;
    let mut output_peak = 0;
    let total = Instant::now();
    for round in 0..rounds {
        app.select(app.panes[round % 4].id);
        let old_cols = app.driver.session.term.cols();
        app.width = if app.width == 1200 { 1200 - 4 * app.driver.renderer.cell_size().0 } else { 1200 };
        let start = Instant::now(); app.relayout().unwrap(); let request_us = start.elapsed().as_micros();
        let marker = format!("ECHO_{round:04}");
        let key = Instant::now(); app.event(Event::Text(format!("\r\n{marker}\r\n")));
        let key_ns = key.elapsed().as_nanos() as usize;
        key_hist[(key_ns / 50000).min(2000)] += 1; key_max = key_max.max(key_ns);
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            if resize_busy(&app) { pending_turns += 1; }
            let time = Instant::now(); assert!(app.tick());
            let ns = time.elapsed().as_nanos() as usize;
            tick_hist[(ns / 50000).min(2000)] += 1; tick_max = tick_max.max(ns); tick_count += 1;
            let time = Instant::now();
            if app.needs_redraw() { app.draw(); }
            paint_max = paint_max.max(time.elapsed().as_nanos() as usize);
            for i in 0..app.panes.len() {
                app.load(i); output_peak = output_peak.max(app.driver.session.resource_bytes().1);
            }
            app.restore();
            if !resize_busy(&app) && text(&app, app.selected).contains(&marker) { break; }
            assert!(Instant::now() < deadline, "UI 缩放/真实 PTY 回显超时");
        }
        assert_ne!(old_cols, app.driver.session.term.cols());
        eprintln!("UI_RESIZE round={round} request_us={request_us} complete_us={} used={} peak={}",
            start.elapsed().as_micros(), crate::resources::current().snapshot().used,
            crate::resources::current().snapshot().peak);
        if round.is_multiple_of(2) { app.add(None); app.close(); wait(&mut app, |a| !resize_busy(a)); }
    }
    assert!(output_peak <= pty::flow::OUTPUT_LIMIT + pty::flow::READ_CHUNK);
    eprintln!("UI_TURNS ticks={tick_count} pending_turns={pending_turns} max_tick_ns={tick_max} max_key_ns={key_max} max_paint_ns={paint_max} output_peak={output_peak} total_us={}", total.elapsed().as_micros());
    eprintln!("UI_TICK_HIST {:?}", tick_hist); eprintln!("UI_KEY_HIST {:?}", key_hist);
    assert_eq!(crate::resources::current().snapshot().kinds[6], 0);
    drop(app);
    let until = Instant::now() + Duration::from_secs(5); let budget = crate::resources::current();
    while budget.snapshot().used != 0 || budget.snapshot().mappings != 0 {
        assert!(Instant::now() < until); std::thread::yield_now();
    }
    eprintln!("BUDGET done used=0 mappings=0");
}
